<script setup lang="ts">
import {ref,watch,onUnmounted} from 'vue';import type {AIContext,AIMessage} from './ai';import {localOpenAIProvider} from './localOpenAIProvider';
const props=defineProps<{context:AIContext}>();const consent=ref(false),draft=ref(''),messages=ref<AIMessage[]>([]),busy=ref(false),error=ref('');let controller:AbortController|null=null;
const label=(zh:string,en:string)=>props.context.locale==='zh'?zh:en;
function cancel(){controller?.abort();controller=null;busy.value=false;}
function reset(){cancel();messages.value=[];draft.value='';error.value='';consent.value=false;}
watch(()=>props.context,reset);onUnmounted(cancel);watch(consent,()=>{cancel();messages.value=[];error.value='';});
async function send(){if(!consent.value||busy.value||!draft.value.trim()||messages.value.length>=4)return;const c=new AbortController();controller=c;busy.value=true;error.value='';const next:AIMessage[]=[...messages.value,{role:'user',text:draft.value.trim()}];try{const answer=await localOpenAIProvider(true).reply(props.context,next,c.signal);if(controller!==c)return;messages.value=[...next,{role:'assistant',text:answer}];draft.value='';}catch{if(controller===c&&!c.signal.aborted)error.value=label('真实服务未启用、额度已用完或请求失败。不会改用模拟回复，也不会自动重试。','Real service disabled, limit reached, or request failed. No mock fallback or automatic retry.');}finally{if(controller===c){controller=null;busy.value=false;}}}
</script>
<template><section class="real-acceptance"><h3>{{label('OpenAI · 受控真实验收','OpenAI · controlled live acceptance')}}</h3><p>{{label('这是付费模型接口，不是离线演示。只有专门启动的受控服务才可用。当前仅允许合成验收问题；默认关闭，测试结束即停止服务。','This is a paid model API, not the offline demo. It requires a separately activated controlled server. Only synthetic acceptance questions are allowed; disabled by default and stopped after testing.')}}</p><label class="reversal"><input type="checkbox" v-model="consent">{{label('同意本轮将当前合成问题、牌阵及对话发送给 OpenAI。取消不能保证免计费。','Allow this synthetic question, current cards and conversation to be sent to OpenAI. Cancelling may still incur cost.')}}</label><template v-if="consent"><div aria-live="polite"><article v-for="(m,i) in messages" :key="i"><strong>{{m.role==='user'?label('你','You'):'OpenAI · gpt-6-luna'}}</strong><p class="real-answer">{{m.text}}</p></article></div><form @submit.prevent="send"><label for="real-message">{{label('真实验收消息','Live acceptance message')}}</label><textarea id="real-message" v-model="draft" maxlength="500" :disabled="busy"></textarea><button type="submit" :disabled="busy||!draft.trim()||messages.length>=4">{{busy?label('等待真实回复…','Waiting for real response…'):label('发送至 OpenAI','Send to OpenAI')}}</button><button v-if="busy" type="button" @click="cancel">{{label('取消真实请求','Cancel real request')}}</button></form><p v-if="error" role="alert">{{error}}</p></template></section></template>
<style scoped>.real-acceptance{border-top:1px solid #d5d5cd;margin-top:2rem;padding-top:1.5rem}.real-answer{white-space:pre-wrap;overflow-wrap:anywhere}button{margin:.5rem .5rem .5rem 0}</style>
